def parse_date_value(value):
    if value is None:
        return None

    text = str(value).strip()

    if not text:
        return None

    # 民國年文字格式，例如 115年11月10日。
    match = re.search(
        r"(\d{3,4})\s*年\s*(\d{1,2})\s*月\s*(\d{1,2})\s*日",
        text
    )

    if match:
        year, month, day_value = map(
            int,
            match.groups()
        )

        if year < 1912:
            year += 1911

        try:
            return date(
                year,
                month,
                day_value
            ).isoformat()
        except ValueError:
            return None

    digits = re.sub(r"\D", "", text)

    try:
        if len(digits) == 7:
            return date(
                int(digits[:3]) + 1911,
                int(digits[3:5]),
                int(digits[5:7]),
            ).isoformat()

        if len(digits) == 8:
            year = int(digits[:4])

            if year >= 1912:
                return date(
                    year,
                    int(digits[4:6]),
                    int(digits[6:8])
                ).isoformat()

    except ValueError:
        return None

    return None

def check_market_quality(market, rows):
    codes = []
    missing_code = 0
    zero_volume = 0
    missing_volume = 0

    ohlc_missing = {
        key: 0
        for key in OHLC_KEYS
    }

    for row in rows:
        code = str(
            find_value_by_keys(row, CODE_KEYS) or ""
        ).strip()

        if not code:
            missing_code += 1
        else:
            codes.append(code)

        volume_value = find_value_by_keys(
            row,
            VOLUME_KEYS
        )

        volume = to_number(volume_value)

        if (
            volume_value is None
            or str(volume_value).strip() == ""
        ):
            missing_volume += 1
        elif volume == 0:
            zero_volume += 1

        for field, aliases in OHLC_KEYS.items():
            value = find_value_by_keys(
                row,
                aliases
            )

            if (
                value is None
                or str(value).strip() in ("", "-", "----")
            ):
                ohlc_missing[field] += 1

    seen = set()
    duplicates = []

    for code in codes:
        if code in seen:
            duplicates.append(code)

        seen.add(code)

    return {
        "market": market,
        "row_count": len(rows),
        "unique_code_count": len(set(codes)),
        "missing_code_rows": missing_code,
        "duplicate_code_count": len(duplicates),
        "duplicate_codes": sorted(set(duplicates)),
        "zero_volume_rows": zero_volume,
        "missing_volume_rows": missing_volume,
        "ohlc_missing_rows": ohlc_missing,
        "note": (
            "零成交量、OHLC 缺漏及重複代號均列入檢核，"
            "不自行改寫官方資料。"
        ),
    }

def save_notebook_source(output_dir):
    code_dir = output_dir / "程式碼"
    code_dir.mkdir(parents=True, exist_ok=True)

    script_path = code_dir / "SSO_v138_daily.py"

    try:
        ip = get_ipython()
        history = ip.history_manager.input_hist_raw

        if history:
            source = history[-1]

            if (
                isinstance(source, str)
                and len(source) > 1000
            ):
                script_path.write_text(
                    source,
                    encoding="utf-8"
                )

                log(
                    f"[PASS] notebook 程式碼已保存：{script_path}"
                )

                return str(script_path)

    except Exception as exc:
        log(
            f"[WARN] 無法擷取 notebook 原始碼：{exc}"
        )

    script_path.write_text(
        "# 無法從 notebook 自動擷取完整原始碼；"
        "請以本對話中的 v1.3.8 完整程式碼為準。\n",
        encoding="utf-8",
    )

    return str(script_path)

def create_zip(output_dir, zip_path):
    with zipfile.ZipFile(
        zip_path,
        "w",
        compression=zipfile.ZIP_DEFLATED,
        compresslevel=6
    ) as zf:

        for path in sorted(output_dir.rglob("*")):
            if (
                path.is_file()
                and path.name != "GitHub與main核對結果.json"
            ):
                zf.write(
                    path,
                    path.relative_to(CONTINUATION_ROOT)
                )

    with zipfile.ZipFile(zip_path, "r") as zf:
        bad_member = zf.testzip()

        if bad_member:
            raise RuntimeError(
                f"ZIP CRC 錯誤：{bad_member}"
            )

    return {
        "path": str(zip_path),
        "bytes": zip_path.stat().st_size,
        "sha256": sha256_file(zip_path),
    }

def github_put_file(
    token,
    branch,
    remote_path,
    content,
    message
):
    url = (
        f"https://api.github.com/repos/{REPO}/contents/"
        f"{quote(remote_path, safe='/')}"
    )

    # Contents API 更新既有檔案時必須附上目前 blob SHA。
    check = requests.get(
        url,
        params={"ref": branch},
        headers={
            "Authorization": f"Bearer {token}",
            "Accept": "application/vnd.github+json",
            "X-GitHub-Api-Version": "2022-11-28",
            "User-Agent": "SSO-Market-Data-Continuation-v1.3.8",
        },
        timeout=120,
    )

    if check.status_code == 200:
        current_sha = check.json().get("sha")

    elif check.status_code == 404:
        current_sha = None

    else:
        raise RuntimeError(
            f"GitHub 檢查既有檔案失敗 HTTP {check.status_code}: "
            f"{check.text[:800]}"
        )

    body = {
        "message": message,
        "content": base64.b64encode(
            content
        ).decode("ascii"),
        "branch": branch,
    }

    if current_sha:
        body["sha"] = current_sha

    response = gh_request(
        "PUT",
        url,
        token,
        json=body
    )

    return response.json()

def github_readback(
    branch,
    remote_path,
    expected_sha256
):
    raw_url = (
        f"https://raw.githubusercontent.com/{REPO}/"
        f"{branch}/{quote(remote_path, safe='/')}"
    )

    response = requests.get(
        raw_url,
        timeout=120
    )

    response.raise_for_status()

    actual = sha256_bytes(response.content)

    if actual != expected_sha256:
        raise RuntimeError(
            f"GitHub readback SHA256 不符：{remote_path}"
        )

    return actual

