def parse_date_value(value):
    if value is None:
        return None

    text = str(value).strip()

    if not text:
        return None

    # 民國年文字格式，例如 115年11月10日。
    match = re.search(
        r"(\d{3,4})\s*年\s*(\d{1,2})\s*月\s*(\d{1,2})\s*日",
        text
    )

    if match:
        year, month, day_value = map(
            int,
            match.groups()
        )

        if year < 1912:
            year += 1911

        try:
            return date(
                year,
                month,
                day_value
            ).isoformat()
        except ValueError:
            return None

    digits = re.sub(r"\D", "", text)

    try:
        if len(digits) == 7:
            return date(
                int(digits[:3]) + 1911,
                int(digits[3:5]),
                int(digits[5:7]),
            ).isoformat()

        if len(digits) == 8:
            year = int(digits[:4])

            if year >= 1912:
                return date(
                    year,
                    int(digits[4:6]),
                    int(digits[6:8])
                ).isoformat()

    except ValueError:
        return None

    return None

def check_market_quality(market, rows):
    codes = []
    missing_code = 0
    zero_volume = 0
    missing_volume = 0

    ohlc_missing = {
        key: 0
        for key in OHLC_KEYS
    }

    for row in rows:
        code = str(
            find_value_by_keys(row, CODE_KEYS) or ""
        ).strip()

        if not code:
            missing_code += 1
        else:
            codes.append(code)

        volume_value = find_value_by_keys(
            row,
            VOLUME_KEYS
        )

        volume = to_number(volume_value)

        if (
            volume_value is None
            or str(volume_value).strip() == ""
        ):
            missing_volume += 1
        elif volume == 0:
            zero_volume += 1

        for field, aliases in OHLC_KEYS.items():
            value = find_value_by_keys(
                row,
                aliases
            )

            if (
                value is None
                or str(value).strip() in ("", "-", "----")
            ):
                ohlc_missing[field] += 1

    seen = set()
    duplicates = []

    for code in codes:
        if code in seen:
            duplicates.append(code)

        seen.add(code)

    return {
        "market": market,
        "row_count": len(rows),
        "unique_code_count": len(set(codes)),
        "missing_code_rows": missing_code,
        "duplicate_code_count": len(duplicates),
        "duplicate_codes": sorted(set(duplicates)),
        "zero_volume_rows": zero_volume,
        "missing_volume_rows": missing_volume,
        "ohlc_missing_rows": ohlc_missing,
        "note": (
            "零成交量、OHLC 缺漏及重複代號均列入檢核，"
            "不自行改寫官方資料。"
        ),
    }

