        timeout=180,
        **kwargs
    )

    if r.status_code >= 400:
        raise RuntimeError(
            f"GitHub HTTP {r.status_code}: {r.text[:1000]}"
        )

    return r

def github_upload_file(token: str, branch: str, path: str, data: bytes) -> dict:
    url = f"https://api.github.com/repos/{REPO}/contents/{quote(path, safe='/')}"

    check = requests.get(
        url,
        params={"ref": branch},
        headers={
            "Authorization": f"Bearer {token}",
            "Accept": "application/vnd.github+json",
            "X-GitHub-Api-Version": "2022-11-28"
        },
        timeout=90
    )

    body = {
        "message": f"SSO v1.4.2 historical market-data gap archive: {Path(path).name}",
        "content": base64.b64encode(data).decode("ascii"),
        "branch": branch
    }

    if check.status_code == 200:
        body["sha"] = check.json()["sha"]
    elif check.status_code != 404:
        raise RuntimeError(
            f"GitHub preflight HTTP {check.status_code}: {check.text[:500]}"
        )

    return github_request("PUT", url, token, json=body).json()

def github_readback_sha(branch: str, path: str) -> str:
    url = (
        f"https://raw.githubusercontent.com/{REPO}/"
        f"{branch}/{quote(path, safe='/')}"
    )
    r = requests.get(url, timeout=180)
    r.raise_for_status()
    return sha256_bytes(r.content)

def create_zip(out: Path, path: Path) -> dict:
    with zipfile.ZipFile(
        path,
        "w",
        compression=zipfile.ZIP_DEFLATED,
        compresslevel=6
    ) as z:
        for f in sorted(out.rglob("*")):
            if f.is_file() and f.name != "GitHub與main核對結果.json":
                z.write(
                    f,
                    arcname=f"{out.name}/{f.relative_to(out).as_posix()}"
                )

    with zipfile.ZipFile(path, "r") as z:
        bad = z.testzip()
        if bad:
            raise RuntimeError(f"ZIP CRC fail: {bad}")

    return {
        "path": str(path),
        "bytes": path.stat().st_size,
        "sha256": sha256_file(path)
    }

def norm(value):

    return re.sub(
        r"[\s\u3000_\-（）()\[\]／/：:、,.%]+",
        "",
        str(value).strip().lower()
    )

def parse_date(value):

    if value is None:
        return None

    s = str(value).strip()

    if not s:
        return None

    s = s.split("T")[0].split(" ")[0]

    m = re.fullmatch(
        r"(\d{2,4})[/-](\d{1,2})[/-](\d{1,2})",
        s
    )

    if m:

        year, month, day = map(
            int,
            m.groups()
        )

        if year < 1911:
            year += 1911

        try:
            return date(year, month, day)
        except ValueError:
            return None

    m = re.fullmatch(
        r"(\d{4})(\d{2})(\d{2})",
        s
    )

    if m:

        try:
            return date(
                *map(int, m.groups())
            )
        except ValueError:
            return None

    return None

def read_csv_rows(path):

    raw = Path(path).read_bytes()

    decoded = None

    for encoding in (
        "utf-8-sig",
        "cp950",
        "big5",
        "gb18030"
    ):

        try:
            decoded = raw.decode(encoding)
            break

        except Exception:
            continue

    if decoded is None:
        raise RuntimeError(
            f"無法解碼 CSV：{path}"
        )

    reader = csv.DictReader(
        io.StringIO(decoded)
    )

    columns = list(
        reader.fieldnames or []
    )

    rows = list(reader)

    if not columns:
        raise RuntimeError(
            f"CSV 缺少表頭：{path}"
        )

    return columns, rows

def normalize_csv_rows(
    path,
    market=None,
    required_fields=None
):

    columns, rows = read_csv_rows(path)

    mapping = make_mapping(columns)

    required_fields = (
        required_fields
        if required_fields is not None
        else CORE_REQUIRED_FIELDS
    )

    missing = [
        field
        for field in required_fields
        if mapping.get(field) is None
    ]

    if missing:
        raise RuntimeError(
            f"{Path(path).name} 缺少必要欄位：{missing}"
        )

    records = []

    for row in rows:

        record = {}

        for field in COMPARE_FIELDS:

            column = mapping.get(field)

            value = (
                row.get(column)
                if column is not None
                else None
            )

            record[field] = normalize_value(
                field,
                value
            )

        records.append(record)

    codes = [
        r["instrument_code"]
        for r in records
    ]

    if any(not code for code in codes):

        raise RuntimeError(
            f"{Path(path).name} 存在空白證券代號。"
        )

    if len(codes) != len(set(codes)):

        raise RuntimeError(
            f"{Path(path).name} 存在重複證券代號。"
        )

    if market is not None:

        wrong_market = [
            r["instrument_code"]
            for r in records
            if r["market"] != market
        ]

        if wrong_market:

            raise RuntimeError(
                f"{Path(path).name} 市場別錯誤："
                f"{wrong_market[:10]}"
            )

    return columns, records

def version_dirs():

    items = []

    for path in ROOT.iterdir():

        if not path.is_dir():
            continue

        match = re.match(
            r"v1\.5\.(\d+)_",
            path.name
        )

        if match:

            items.append((
                int(match.group(1)),
                path
            ))

    items.sort(
        key=lambda x: (
            x[0],
            x[1].name
        )
    )

    return [
        item[1]
        for item in items
    ]

