def validate_records(
    records,
    market,
    day,
    expected_rows
):

    errors = []

    n = len(records)

    codes = [
        str(r.get("instrument_code", "")).strip()
        for r in records
    ]

    unique_codes = len(set(codes))

    duplicate_count = n - unique_codes

    invalid_codes = [
        code
        for code in codes
        if not re.fullmatch(
            rf"[0-9A-Za-z.\-]{{{MIN_CODE_LENGTH},{MAX_CODE_LENGTH}}}",
            code
        )
    ]

    if n < MIN_ROWS_ABSOLUTE:
        errors.append(
            f"資料筆數低於絕對下限：{n}"
        )

    if n > MAX_ROWS_ABSOLUTE:
        errors.append(
            f"資料筆數超過絕對上限：{n}"
        )

    if expected_rows:

        lower = expected_rows * MIN_COUNT_RATIO
        upper = expected_rows * MAX_COUNT_RATIO

        if not lower <= n <= upper:

            errors.append(
                "資料筆數偏離歷史母體："
                f"本次={n}；基準={expected_rows}；"
                f"允許={lower:.0f}~{upper:.0f}"
            )

    if duplicate_count:
        errors.append(
            f"重複證券代號列數={duplicate_count}"
        )

    if invalid_codes:
        errors.append(
            f"不合法證券代號列數={len(invalid_codes)}"
        )

    wrong_date = sum(
        r.get("trade_date") != day.isoformat()
        for r in records
    )

    wrong_market = sum(
        market_norm(r.get("market")) != market
        for r in records
    )

    if wrong_date:
        errors.append(
            f"交易日期不符列數={wrong_date}"
        )

    if wrong_market:
        errors.append(
            f"市場別不符列數={wrong_market}"
        )

    missing_volume = sum(
        r.get("volume") is None
        for r in records
    )

    negative_volume = sum(
        r.get("volume") is not None
        and r["volume"] < 0
        for r in records
    )

    i

