def save_current_source(out_dir, logs):

    target = (
        Path(out_dir)
        / f"{VERSION}.py"
    )

    source_text = ""

    try:

        ip = get_ipython()

        history = (
            ip.history_manager.input_hist_raw
        )

        for candidate in reversed(
            history[-10:]
        ):

            if (
                VERSION in candidate
                and "def run_v1510" in candidate
            ):

                source_text = candidate
                break

    except Exception:
        source_text = ""

    if source_text:

        target.write_text(
            source_text,
            encoding="utf-8"
        )

        log(
            "[SOURCE PASS] 完整 v1.5.10 程式已封存。",
            logs
        )

        return target

    # 不因 Colab history 無法取得而丟失本次行情成果。
    note = (
        "本次執行程式已完整提供於 ChatGPT 對話；"
        "Colab IPython history 無法擷取目前儲存格。"
    )

    target.write_text(
        "# SOURCE CAPTURE NOTE\n"
        + note
        + "\n",
        encoding="utf-8"
    )

    log(
        "[SOURCE WARNING] Colab 未能擷取完整 cell source；"
        "程式仍由對話保存。",
        logs
    )

    return target

def make_and_verify_zip(
    out_dir,
    zip_path,
    manifest
):

    out_dir = Path(out_dir)
    zip_path = Path(zip_path)

    with zipfile.ZipFile(
        zip_path,
        "w",
        compression=zipfile.ZIP_DEFLATED,
        compresslevel=6
    ) as zf:

        for path in sorted(out_dir.rglob("*")):

            if not path.is_file():
                continue

            if path == zip_path:
                continue

            if path.name == "GitHub上傳結果.json":
                continue

            if path.suffix.lower() == ".zip":
                continue

            zf.write(
                path,
                path.relative_to(out_dir).as_posix()
            )

    with zipfile.ZipFile(
        zip_path,
        "r"
    ) as zf:

        bad_member = zf.testzip()

        if bad_member:

            raise RuntimeError(
                f"ZIP CRC 驗證失敗：{bad_member}"
            )

        names = set(zf.namelist())

        for item in manifest["files"]:

            relative = item["path"]

            if relative not in names:

                raise RuntimeError(
                    f"ZIP 缺少封存檔案：{relative}"
                )

            data = zf.read(relative)

            if sha256_bytes(data) != item["sha256"]:

                raise RuntimeError(
                    f"ZIP 內檔案 SHA256 不一致：{relative}"
                )

    return {
        "zip_bytes": zip_path.stat().st_size,
        "zip_sha256": sha256_file(zip_path),
        "crc_pass": True,
        "manifest_file_count": manifest["file_count"],
        "manifest_readback_pass": True
    }

def req(method, path, **kwargs):

        response = session.request(
            method,
            api + path,
            timeout=(20, 180),
            **kwargs
        )

        if not response.ok:

            raise RuntimeError(
                f"GitHub API HTTP {response.status_code}: "
                f"{response.text[:1500]}"
            )

        return (
            response.json()
            if response.content
            else {}
        )

def norm_label(x):

