def make_zip(out_dir, zip_path):

    with zipfile.ZipFile(
        zip_path,
        "w",
        compression=zipfile.ZIP_DEFLATED,
        compresslevel=6
    ) as zf:

        for p in sorted(
            Path(out_dir).rglob("*")
        ):

            if p.is_file() and p != zip_path:

                zf.write(
                    p,
                    p.relative_to(out_dir).as_posix()
                )

