def norm(x):

    return re.sub(
        r"[\s\u3000_\-（）()【】\[\]／/：:、,.%]+",
        "",
        str(x).strip().lower()
    )

def read_header(path):

    raw = Path(path).read_bytes()

    for enc in (
        "utf-8-sig",
        "cp950",
        "big5",
        "gb18030"
    ):

        try:

            return next(
                csv.reader(
                    io.StringIO(
                        raw.decode(enc)
                    )
                )
            )

        except Exception:
            pass

    raise RuntimeError(
        f"無法讀取欄位表頭：{path}"
    )

