def validate_download(
    records,
    market,
    day,
    expected_rows
):

    errors = []

    n = len(records)

    codes = [
        r["instrument_code"]
        for r in records
    ]

    unique_codes = len(set(codes))

    duplicate_count = n - unique_codes

    if n < MIN_ROWS_ABSOLUTE:

        errors.append(
            f"資料筆數低於 {MIN_ROWS_ABSOLUTE}：{n}"
        )

    if n > MAX_ROWS_ABSOLUTE:

        errors.append(
            f"資料筆數超過 {MAX_ROWS_ABSOLUTE}：{n}"
        )

    if expected_rows:

        lower = expected_rows * MIN_COUNT_RATIO

        upper = expected_rows * MAX_COUNT_RATIO

        if not (
            lower <= n <= upper
        ):

            errors.append(
                f"資料筆數偏離既有母體："
                f"本次={n}；"
                f"既有中位數={expected_rows}；"
                f"允許={lower:.0f}~{upper:.0f}"
            )

    if duplicate_count > 0:

        errors.append(
            f"重複代號列數={duplicate_count}"
        )

    if not records:

        errors.append(
            "沒有可寫入行情列"
        )

    zero_volume = sum(
        r["volume"] == 0
        for r in records
        if r["volume"] is not None
    )

    missing_volume = sum(
        r["volume"] is None
        for r in records
    )

    missing_ohlc_rows = sum(
        any(
            r[k] is None
            for k in ("open", "high", "low", "close")
        )
        for r in records
    )

    zero_ratio = (
        zero_volume / n
        if n
        else 0
    )

    missing_ohlc_ratio = (
        missing_ohlc_rows / n
        if n
        else 0
    )

    if missing_volume:

        errors.append(
            f"成交量無法解析列數={missing_volume}"
        )

    if zero_ratio > MAX_ZERO_VOLUME_RATIO:

        errors.append(
            f"零成交量比例異常：{zero_ratio:.1%}"
        )

    i

