def safe_num(value, integer=False):
    # 修正舊版 0 被當成空值的問題。
    if value is None:
        return None

    s = (
        str(value)
        .strip()
        .replace(",", "")
        .replace("＋", "+")
        .replace("－", "-")
    )

    if s in {"", "-", "--", "---", "X", "x", "N/A", "nan", "None"}:
        return None

    try:
        number = float(s)

        if not pd.notna(number):
            return None

        if integer:
            return int(round(number))

        return number

    except Exception:
        return None

