def is_close_value(a: Any, b: Any, tol: float = 1e-12) -> bool:
    a_na = pd.isna(a)
    b_na = pd.isna(b)

    if a_na and b_na:
        return True

    if a_na != b_na:
        return False

    try:
        return bool(
            np.isclose(
                float(a),
                float(b),
                atol=tol,
                rtol=0,
                equal_nan=True,
            )
        )
    except Exception:
        return str(a) == str(b)

def is_same_bool(a: Any, b: Any) -> bool:
    def convert(x):
        if isinstance(x, (bool, np.bool_)):
            return bool(x)
        if pd.isna(x):
            return None
        value = str(x).strip().lower()
        if value in ("true", "1", "yes", "是"):
            return True
        if value in ("false", "0", "no", "否"):
            return False
        return None

    return convert(a) == convert(b)

def convert(x):
        if isinstance(x, (bool, np.bool_)):
            return bool(x)
        if pd.isna(x):
            return None
        value = str(x).strip().lower()
        if value in ("true", "1", "yes", "是"):
            return True
        if value in ("false", "0", "no", "否"):
            return False
        return None

