def normalize_col(value):
    value = unicodedata.normalize(
        "NFKC",
        str(value),
    ).lower()

    return re.sub(
        r"[^0-9a-z\u4e00-\u9fff]",
        "",
        value,
    )

def history_candidate_score(path):
    name = path.name.lower()

    score = 0

    if "v2.31" in name:
        score += 100

    if "v231" in name:
        score += 90

    if "含ohlc" in name:
        score += 70

    if "計算主表" in name:
        score += 60

    if "ohlc" in name:
        score += 40

    if path.suffix.lower() in {".csv", ".gz"}:
        score += 10

    return score

