    path = Path(path)

    last_error = None

    for encoding in (
        "utf-8-sig",
        "cp950",
        "big5",
        "gb18030",
    ):

        try:

            return pd.read_csv(
                path,
                dtype="string",
                encoding=encoding,
                low_memory=False,
            )

        except Exception as error:

            last_error = error

    raise RuntimeError(
