def archive_current_program(out_dir):

    target = (
        out_dir
        / "SSO_v1.3.1_凍結12檔前瞻樣本外追蹤.py"
    )

    source_text = ""

    try:

        shell = get_ipython()

        history = (
            shell.history_manager.input_hist_raw
        )

        for candidate in reversed(
            history
        ):

            if not isinstance(candidate, str):
                continue

            if (
                "SSO v1.3.1｜凍結12檔前瞻樣本外追蹤主程式"
                in candidate
                and "def run_main_v131():" in candidate
                and len(candidate) > 20000
            ):

                source_text = candidate
                break

    except Exception:
        source_text = ""

    if source_text:

        compile(
            source_text,
            str(target),
            "exec"
        )

        target.write_text(
            source_text,
            encoding="utf-8"
        )

        return target

    target.write_text(
        "# SOURCE_CAPTURE_NOTE\n"
        "本次完整程式原文已由 ChatGPT 對話提供；"
        "Colab IPython history 未能自動擷取目前儲存格。\n",
        encoding="utf-8"
    )

    return target

def make_and_verify_zip(
    out_dir,
    zip_path,
    manifest
):

    out_dir = Path(out_dir)
    zip_path = Path(zip_path)

    with zipfile.ZipFile(
        zip_path,
        "w",
        compression=zipfile.ZIP_DEFLATED,
        compresslevel=6
    ) as archive:

        for path in sorted(
            out_dir.rglob("*")
        ):

            if not path.is_file():
                continue

            if path == zip_path:
                continue

            if path.name == "GitHub上傳結果.json":
                continue

            archive.write(
                path,
                path.relative_to(out_dir).as_posix()
            )

    with zipfile.ZipFile(
        zip_path,
        "r"
    ) as archive:

        bad = archive.testzip()

        if bad:
            raise RuntimeError(
                f"ZIP CRC 失敗：{bad}"
            )

        names = set(
            archive.namelist()
        )

        for item in manifest["files"]:

            relative = item["path"]

            if relative not in names:

                raise RuntimeError(
                    f"ZIP 缺少檔案：{relative}"
                )

            if sha256_bytes(
                archive.read(relative)
            ) != item["sha256"]:

                raise RuntimeError(
                    f"ZIP 內部 SHA256 不一致：{relative}"
                )

        manifest_data = archive.read(
            "artifact_sha256_manifest.json"
        )

        local_manifest_sha = sha256_file(
            out_dir / "artifact_sha256_manifest.json"
        )

        if sha256_bytes(
            manifest_data
        ) != local_manifest_sha:

            raise RuntimeError(
                "ZIP 內 manifest SHA 不一致。"
            )

    return {
        "zip_bytes": zip_path.stat().st_size,
        "zip_sha256": s

