def sha256_file(path, chunk=8 * 1024 * 1024):
    h = hashlib.sha256()

    with open(path, "rb") as f:
        for block in iter(lambda: f.read(chunk), b""):
            h.update(block)

    return h.hexdigest()

def json_write(obj, path):
    Path(path).write_text(
        json.dumps(
            obj,
            ensure_ascii=False,
            indent=2,
            default=str,
        ),
        encoding="utf-8-sig",
    )

def safe_int(value, default=0):
    try:
        return int(value)
    except Exception:
        return default

def open_candidate_stream(candidate):
    """回傳解壓後的位元組串流；SHA256 對解壓後內容計算。"""

    if candidate["source_kind"] == "FILE":
        path = Path(candidate["path"])
        raw = open(path, "rb")

        try:
            if str(path).lower().endswith((".gz", ".csv.gz", ".json.gz")):
                with gzip.GzipFile(fileobj=raw, mode="rb") as gz:
                    yield gz
            else:
                yield raw
        finally:
            raw.close()

        return

    archive_path = Path(candidate["archive_path"])
    member = candidate["member"]

    with zipfile.ZipFile(archive_path, "r") as zf:
        with zf.open(member, "r") as raw:
            if str(member).lower().endswith((".gz", ".csv.gz", ".json.gz")):
                with gzip.GzipFile(fileobj=raw, mode="rb") as gz:
                    yield gz
            else:
                yield raw

def decode_sample(sample):
    best = None
    best_score = float("inf")

    for encoding in (
        "utf-8-sig", "utf-8", "cp950",
        "big5", "gb18030", "utf-16",
    ):
        try:
            decoded = sample.decode(
                encoding,
                errors="replace",
            )

            replacement = decoded.count("\ufffd")
            score = replacement / max(1, len(decoded))

            if score < best_score:
                best, best_score = (decoded, encoding), score

            if replacement == 0:
                return decoded, encoding

        except Exception:
            continue

    if best is None:
        return sample.decode("utf-8", errors="replace"), "utf-8"

    return best

def detect_delimiter(text, filename):
    if str(filename).lower().endswith((".tsv", ".tab")):
        return "\t"

    lines = [
        x for x in text.splitlines()[:30]
        if x.strip()
    ]

    if not lines:
        return ","

    sample = "\n".join(lines[:20])

    try:
        return csv.Sniffer().sniff(
            sample,
            delimiters=",\t;|",
        ).delimiter

    except Exception:
        scores = {}

        for sep in [",", "\t", ";", "|"]:
            counts = [
                line.count(sep)
                for line in lines[:10]
            ]

            scores[sep] = (
                sum(counts),
                len(set(counts)),
            )

        return max(
            scores,
            key=lambda x: (
                scores[x][0],
                -scores[x][1],
            ),
        )

def read_header(candidate):
    with open_candidate_stream(candidate) as stream:
        sample = stream.read(SAMPLE_BYTES)

    decoded, encoding = decode_sample(sample)

    sep = detect_delimiter(
        decoded,
        candidate.get("member") or candidate.get("path", ""),
    )

    try:
        header = pd.read_csv(
            io.StringIO(decoded),
            sep=sep,
            nrows=0,
            engine="python",
            on_bad_lines="skip",
        )

        columns = [
            str(x).replace("\ufeff", "").strip()
            for x in header.columns
        ]

    except Exception as exc:
        raise RuntimeError(
            f"標頭解析失敗：{type(exc).__name__}: {exc}"
        )

    if len(columns) > MAX_HEADER_COLUMNS:
        raise RuntimeError(
            f"欄位數超過限制：{len(columns)}"
        )

    return columns, encoding, sep

def cfi_valid_mask(series):
    text = (
        series.astype("string")
        .str.strip()
        .str.upper()
    )

    return text.str.fullmatch(
        r"[A-Z0-9]{6}",
        na=False,
    )

def enumerate_sources(root, out_dir):
    physical = []
    archives = []
    table_candidates = []
    json_candidates = []

    walk_dirs = 0
    walk_files = 0

    excluded_dirs = {
        ".ipynb_checkpoints",
        "__pycache__",
        ".Trash",
        ".trash",
        ".git",
        "node_modules",
    }

    for current, dirs, files in os.walk(
        root,
        topdown=True,
        followlinks=False,
    ):
        walk_dirs += 1

        dirs[:] = [
            d for d in dirs
            if d not in excluded_dirs
            and not d.startswith(".tmp")
            and (Path(current) / d).resolve() != out_dir.resolve()
        ]

        for filename in files:
            path = Path(current) / filename
            walk_files += 1

            if out_dir.resolve() in path.resolve().parents:
                continue

            if path == ZIP_PATH:
                continue

            if filename.startswith("~$") or filename.endswith(".tmp"):
                continue

            try:
                stat = path.stat()
            except Exception:
                continue

            relative = str(path.relative_to(root))
            lower = filename.lower()

            if lower.endswith(ARCHIVE_EXTENSION):
                archives.append({
                    "path": path,
                    "relative_path": relative,
                    "size": int(stat.st_size),
                    "mtime": datetime.fromtimestamp(
                        stat.st_mtime,
                        TAIPEI,
                    ).isoformat(),
                })

            elif is_table_name(lower):
                candidate = {
                    "source_kind": "FILE",
                    "path": path,
                    "relative_path": relative,

