def archive_current_program(out_dir):
    target = (
        out_dir
        / "SSO_v1.3.1_歷史OHLC與逐日證券分類來源精確驗證.py"
    )

    source = None

    try:
        shell = get_ipython()
        history = shell.history_manager.input_hist_raw

        for candidate in reversed(history):
            if (
                isinstance(candidate, str)
                and "SSO v1.3.1" in candidate
                and "def run_v131()" in candidate
                and "def scan_csv_candidate(" in candidate
                and len(candidate) > 25000
            ):
                source = candidate
                break

    except Exception:
        pass

    if not source:
        try:
            history = globals().get("In", [])

            for candidate in reversed(history):
                if (
                    isinstance(candidate, str)
                    and "SSO v1.3.1" in candidate
                    and "def run_v131()" in candidate
                    and len(candidate) > 25000
                ):
                    source = candidate
                    break

        except Exception:
            pass

    if not source:
        raise RuntimeError(
            "無法從 Colab 執行歷史取得完整 v1.3.1 程式原文，停止封存。"
        )

    compile(
        source,
        str(target),
        "exec",
    )

    target.write_text(
        source,
        encoding="utf-8",
    )

    return target

def parse_date(v: Any) -> Optional[str]:
    s = clean(v).replace("\ufeff", "").split(" ")[0]
    if not s:
        return None
    if re.fullmatch(r"\d+\.0+", s):
        s = s.split(".", 1)[0]
    if re.fullmatch(r"\d{8}", s):
        try:
            return datetime.strptime(s, "%Y%m%d").date().isoformat()
        except ValueError:
            return None
    if re.fullmatch(r"\d{7}", s):
        try:
            return date(int(s[:3]) + 1911, int(s[3:5]), int(s[5:7])).isoformat()
        except Exception:
            return None
    m = re.fullmatch(r"(\d{2,4})[-/.](\d{1,2})[-/.](\d{1,2})", s)
    if m:
        y, mo, d = map(int, m.groups())
        if y < 1911:
            y += 1911
        try:
            return date(y, mo, d).isoformat()
        except ValueError:
            return None
    try:
        x = pd.to_datetime(s, errors="coerce")
        return None if pd.isna(x) else x.date().isoformat()
    except Exception:
        return None

def norm_code(v: Any) -> str:
    s = clean(v).replace(" ", "")
    if re.fullmatch(r"\d+\.0+", s):
        s = s.split(".", 1)[0]
    return s.upper()

def find_col(cols: Sequence[str], aliases: Sequence[str]) -> Optional[str]:
    cmap = {norm(c): str(c) for c in cols}
    for a in aliases:
        if norm(a) in cmap:
            return cmap[norm(a)]
    for a in aliases:
        na = norm(a)
        hits = [str(c) for c in cols if na and na in norm(c)]
        if len(hits) == 1:
            return hits[0]
    return None

def check_acceptance(dir_path: Path) -> Tuple[bool, str]:
    summary = dir_path / "v4.68.4執行摘要.txt"
    if summary.exists():
        txt = summary.read_text(encoding="utf-8-sig", errors="replace")
        if "PASS_FOR_SORTING_AND_FEATURE_REBUILD_NOT_MODEL_READY" in txt:
            return True, "PASS_FOR_SORTING_AND_FEATURE_REBUILD_NOT_MODEL_READY"
    gate = dir_path / "01_候選資料驗收品質閘門.csv"
    if gate.exists():
        df = read_csv_small(gate)
        text = " ".join(df.astype(str).fillna("").to_numpy().ravel().tolist())
        if "PASS" in text and "FAIL" not in text:
            return True, "PASS_FROM_GATE_TABLE"
    return False, "V4684_ACCEPTANCE_NOT_CONFIRMED"

