def write_df(path: Path, rows: Any) -> None:
    df = rows if isinstance(rows, pd.DataFrame) else pd.DataFrame(list(rows))
    df.to_csv(path, index=False, encoding="utf-8-sig")

def sha256_file(path: Path, label: str, block: int = 8 * 1024 * 1024) -> str:
    h = hashlib.sha256()
    size = path.stat().st_size
    done = 0
    started = time.monotonic()
    with path.open("rb") as f:
        while True:
            b = f.read(block)
            if not b:
                break
            h.update(b)
            done += len(b)
            if done == size or done % max(block, size // 5) < block:
                log(f"SHA256 {label} {bar(done / max(1, size) * 100)} | {done/1024**2:,.1f}/{size/1024**2:,.1f} MB | {elapsed(time.monotonic()-started)}")
    return h.hexdigest()

def safe_read_csv(path: Path) -> pd.DataFrame:
    for enc in ("utf-8-sig", "utf-8", "cp950"):
        try:
            return pd.read_csv(path, encoding=enc)
        except UnicodeDecodeError:
            continue
    return pd.read_csv(path, encoding="utf-8", errors="replace")

def discover_v469(root: Path, override: Optional[str]) -> Tuple[Path, Path]:
    if override:
        d = Path(override)
        cands = list(d.glob("01_v231補行日日期排序與已驗證特徵重建候選.csv.gz"))
        if not cands:
            raise FileNotFoundError(f"指定 v4.69 資料夾找不到候選 CSV.GZ：{d}")
        return d, cands[0]
    dirs = sorted(root.glob("看股最速適_v231補行日日期排序與已驗證特徵重建_v4_69_*"), key=lambda p: p.stat().st_mtime)
    for d in reversed(dirs):
        c = d / "01_v231補行日日期排序與已驗證特徵重建候選.csv.gz"
        if c.exists():
            return d, c
    raise FileNotFoundError("找不到 v4.69 日期排序候選資料夾；請確認 Drive 已掛載或使用 --v469-dir 指定。")

def normalized_feature_scales(v469_dir: Path) -> Dict[str, float]:
    p = v469_dir / "01_已驗證特徵公式重現核對.csv"
    if not p.exists():
        return {x: 1.0 for x in VERIFIED_FEATURES}
    d = safe_read_csv(p)
    name_col = next((c for c in d.columns if "特徵欄位" in c), None)
    scale_col = next((c for c in d.columns if "最佳倍率" in c), None)
    result = {x: 1.0 for x in VERIFIED_FEATURES}
    if name_col and scale_col:
        for _, r in d.iterrows():
            name = str(r[name_col])
            if name in result:
                try:
                    val = float(r[scale_col])
                    if math.isfinite(val) and val != 0:
                        result[name] = val
                except Exception:
                    pass
    return result

def load_selected_candidate(path: Path) -> pd.DataFrame:
    header = read_header_gz(path)
    required = ["日期", *KEYS, *OHLC, *VERIFIED_FEATURES, *UNVERIFIED_FEATURES, *FORWARD_HORIZONS.keys()]
    missing = [x for x in required if x not in header]
    if missing:
        raise ValueError(f"v4.69 候選缺必要欄位：{missing}")
    usecols = list(dict.fromkeys(required))
    dtypes: Dict[str, Any] = {
        "市場": "category", "股票代號": "category", "價格研究區段": "category",
    }
    for c in OHLC + VERIFIED_FEATURES + UNVERIFIED_FEATURES + list(FORWARD_HORIZONS.keys()):
        dtypes[c] = "float32"
    log(f"載入 v4.69 精簡欄位：{len(usecols)} 欄；大型候選檔 {path.stat().st_size/1024**2:,.1f} MB")
    started = time.monotonic()
    df = pd.read_csv(path, compression="gzip", usecols=usecols, dtype=dtypes, low_memory=False)
    df["日期"] = pd.to_datetime(df["日期"], errors="coerce")
    if df["日期"].isna().any():
        raise ValueError(f"候選日期有 {int(df['日期'].isna().sum())} 列無法解析")
    # Ensure OHLC / feature / labels numeric even if source contains special tokens.
    for c in OHLC + VERIFIED_FEATURES + UNVERIFIED_FEATURES + list(FORWARD_HORIZONS.keys()):
        df[c] = pd.to_numeric(df[c], errors="coerce").astype("float32")
    log(f"候選資料載入完成：{len(df):,} 列；耗時 {elapsed(time.monotonic()-started)}")
    return df

def check_v469_evidence(v469_dir: Path, candidate_rows: int) -> Dict[str, Any]:
    info: Dict[str, Any] = {"rows_report_pass": False, "sat_report_pass": False,
                            "date_report_pass": False, "duplicate_report_pass": False,
                            "feature_formula_pass": 0, "label_formula_pass": 0}
    p = v469_dir / "03_日期排序及列數品質閘門.csv"
    if p.exists():
        d = safe_read_csv(p)
        for _, r in d.iterrows():
            item = str(r.get("項目", ""))
            result = str(r.get("結果", ""))
            if item == "最終總列數":
                try: info["rows_report_pass"] = int(float(result)) == candidate_rows
                except Exception: pass
            elif item == "新增星期六列數":
                try: info["sat_report_pass"] = int(float(result)) == EXPECTED_SATURDAY_ROWS
                except Exception: pass
            elif item == "全資料日期排序":
                info["date_report_pass"] = result.lower() in {"true", "1"}
            elif item == "自然鍵重複":
                try: info["duplicate_report_pass"] = int(float(result)) == 0
                except Exception: pass
    f = v469_dir / "01_已驗證特徵公式重現核對.csv"
    if f.exists():
        d = safe_read_csv(f)
        if "公式判讀" in d.columns:
            info["feature_formula_pass"] = int((d["公式判讀"].astype(str) == "PASS").sum())
    l = v469_dir / "02_前瞻標籤公式重現核對.csv"
    if l.exists():
        d = safe_read_csv(l)
        if "公式判讀" in d.columns:
            info["label_formula_pass"] = int((d["公式判讀"].astype(str) == "PASS").sum())
    return info

def write_gzip_csv_progress(df: pd.DataFrame, path: Path, label: str, chunk: int = 100_000) -> None:
    started = time.monotonic()
    with gzip.open(path, "wt", encoding="utf-8-sig", newline="") as f:
        for start in range(0, len(df), chunk):
            end = min(len(df), start + chunk)
            df.iloc[start:end].to_csv(f, index=False, header=(start == 0), lineterminator="\n")
            log(f"{label} {bar(end/max(1,len(df))*100)} | 已寫 {end:,}/{len(df):,} 列 | {elapsed(time.monotonic()-started)}")

def sha256_file(path: Path, block_size: int = 8 * 1024 * 1024) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        while True:
            block = f.read(block_size)
            if not block:
                break
            h.update(block)
    return h.hexdigest()

