def norm_text(value: Any) -> str:
    if value is None:
        return ""
    s = unicodedata.normalize("NFKC", str(value)).strip().upper()
    s = re.sub(r"\s+", "", s)
    if s.endswith(".0"):
        s = s[:-2]
    return s

def norm_date(value: Any) -> str:
    s = "" if value is None else str(value).strip().split(" ")[0]
    if not s:
        return ""
    if re.fullmatch(r"\d{8}", s):
        return f"{s[:4]}-{s[4:6]}-{s[6:8]}"
    if re.fullmatch(r"\d{7}", s):
        try:
            y = int(s[:3]) + 1911
            return date(y, int(s[3:5]), int(s[5:7])).isoformat()
        except ValueError:
            return ""
    m = re.fullmatch(r"(\d{2,4})[/.](\d{1,2})[/.](\d{1,2})", s)
    if m:
        y, mo, d = map(int, m.groups())
        if y < 1911:
            y += 1911
        try:
            return date(y, mo, d).isoformat()
        except ValueError:
            return ""
    try:
        value_dt = pd.to_datetime(s, errors="coerce")
        return "" if pd.isna(value_dt) else value_dt.strftime("%Y-%m-%d")
    except Exception:
        return ""

def find_v251_zip(stage: Path) -> Path:
    local_candidates = [
        ROOT / V251_ZIP_NAME,
        ROOT / "緊急備份" / "睡前備份_20261028_181527" / "結果ZIP" / V251_ZIP_NAME,
        Path("/content") / V251_ZIP_NAME,
    ]
    for path in local_candidates:
        if path.is_file():
            log(f"使用既有 v2.51 ZIP：{path}")
            result = stage / V251_ZIP_NAME
            if path.resolve() != result.resolve():
                shutil.copy2(path, result)
            break
    else:
        result = stage / V251_ZIP_NAME
        log("找不到本機 v2.51 ZIP，從固定 GitHub commit 下載唯讀來源。")
        response = requests.get(V251_URL, stream=True, timeout=(30, 180))
        response.raise_for_status()
        done = 0
        with result.open("wb") as f:
            for block in response.iter_content(chunk_size=1024 * 1024):
                if block:
                    f.write(block)
                    done += len(block)
                    if done % (5 * 1024 * 1024) < 1024 * 1024:
                        log(f"v2.51 ZIP 下載：{done:,} bytes")
    actual_size = result.stat().st_size
    actual_sha = sha256_file(result)
    if actual_size != V251_SIZE:
        raise RuntimeError(f"v2.51 ZIP 大小不符：{actual_size:,} != {V251_SIZE:,}")
    if actual_sha != V251_SHA256:
        raise RuntimeError(f"v2.51 ZIP SHA256 不符：{actual_sha}；停止使用。")
    log(f"v2.51 ZIP 完整性通過：{actual_size:,} bytes；SHA256 符合固定 commit。")
    return result

