def build_master_zip(stage: Path, pair_dir: Path, v469_dir: Path, v470_dir: Path,
                     source_paths: List[Path], zip_out: Path) -> None:
    members: List[Tuple[Path, str]] = []
    for p in sorted(pair_dir.iterdir()):
        if p.is_file():
            members.append((p, f"逐筆配對/{p.name}"))
    for p in source_paths:
        members.append((p, f"原始程式/{p.name}"))
    v469_zip = next(iter(v469_dir.glob("*.zip")), None)
    if v469_zip:
        members.append((v469_zip, f"v4.69稽核報告/{v469_zip.name}"))
    v470_zip = next(iter(v470_dir.glob("*.zip")), None)
    if v470_zip:
        members.append((v470_zip, f"v4.70.1稽核報告/{v470_zip.name}"))
    zip_out.parent.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(zip_out, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=1) as zf:
        for i, (path, arcname) in enumerate(members, start=1):
            zf.write(path, arcname=arcname)
            if i == 1 or i % 5 == 0 or i == len(members):
                log(f"整合 ZIP 封裝 {i}/{len(members)}：{arcname}")
    with zipfile.ZipFile(zip_out, "r") as zf:
        bad = zf.testzip()
        if bad:
            raise RuntimeError(f"整合 ZIP CRC 驗證失敗：{bad}")
    log(f"整合 ZIP 完成：{zip_out.stat().st_size:,} bytes；SHA256={sha256_file(zip_out)}")

def github_put_file(session: requests.Session, token: str, path: str, content: bytes, message: str) -> dict:
    api_url = f"https://api.github.com/repos/{REPO}/contents/{quote(path, safe='/')}"
    headers = {
        "Accept": "application/vnd.github+json",
        "Authorization": f"Bearer {token}",
        "X-GitHub-Api-Version": "2022-11-28",
        "User-Agent": "SSO-v4.84.9.8-audit-uploader",
    }
    existing_sha = None
    check = session.get(api_url, headers=headers, params={"ref": ACTIONS_RUNNER_BRANCH}, timeout=30)
    if check.status_code == 200:
        existing_sha = check.json().get("sha")
    elif check.status_code != 404:
        raise RuntimeError(f"GitHub 檔案查詢失敗 HTTP {check.status_code}：{check.text[:500]}")
    payload = {
        "message": message,
        "content": __import__("base64").b64encode(content).decode("ascii"),
        "branch": ACTIONS_RUNNER_BRANCH,
    }
    if existing_sha:
        payload["sha"] = existing_sha
    response = session.put(api_url, headers=headers, json=payload, timeout=180)
    if response.status_code not in (200, 201):
        raise RuntimeError(f"GitHub 上傳失敗 HTTP {response.status_code}：{response.text[:800]}")
    data = response.json()
    return {"path": path, "sha": data.get("content", {}).get("sha"), "url": data.get("content", {}).get("html_url")}

def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for block in iter(lambda: f.read(1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()

def write_json(path: Path, obj: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(obj, ensure_ascii=False, indent=2, default=str), encoding="utf-8")

def parse_date(value: Any, path_hint: str = "") -> Optional[str]:
    candidates = []
    if value is not None:
        candidates.append(str(value).strip())
    candidates.append(path_hint)
    for raw in candidates:
        s = str(raw or "").strip()
        m = re.search(r"(?<!\d)(20\d{2})[-/]?(\d{2})[-/]?(\d{2})(?!\d)", s)
        if m:
            y, mo, d = map(int, m.groups())
            try:
                return dt.date(y, mo, d).isoformat()
            except ValueError:
                pass
        m = re.search(r"(?<!\d)(\d{3})[/.-]?(\d{2})[/.-]?(\d{2})(?!\d)", s)
        if m:
            y, mo, d = map(int, m.groups())
            try:
                return dt.date(y + 1911, mo, d).isoformat()
            except ValueError:
                pass
    return None

def decode_bytes(data: bytes) -> str:
    for enc in ("utf-8-sig", "utf-8", "cp950", "big5"):
        try:
            return data.decode(enc)
        except UnicodeDecodeError:
            continue
    return data.decode("utf-8", errors="replace")

def read_csv_records(data: bytes, path_hint: str, market_hint: Optional[str], source_member: str) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    text = decode_bytes(data)
    sample = text[:8192]
    try:
        dialect = csv.Sniffer().sniff(sample, delimiters=",\t;")
    except Exception:
        dialect = csv.excel
    reader = csv.DictReader(io.StringIO(text), dialect=dialect)
    if not reader.fieldnames:
        return [], {"member": source_member, "format": "CSV", "rows": 0, "reason": "NO_HEADER"}
    normalized_headers = [norm_header(x) for x in reader.fieldnames]
    has_code = any(any(norm_header(a) == h or norm_header(a) in h for a in ALIASES["code"]) for h in normalized_headers)
    has_ohlc = all(any(norm_header(a) == h or norm_header(a) in h for a in ALIASES[k] for h in normalized_headers) for k in ("open", "high", "low", "close"))
    if not has_code or not has_ohlc:
        return [], {"member": source_member, "format": "CSV", "rows": 0, "reason": "NO_CODE_OR_OHLC", "headers": reader.fieldnames[:60]}
    out = []
    for row in reader:
        record = normalize_record(row, market_hint, path_hint, source_member, "CSV")
        if record:
            out.append(record)
    return out, {"member": source_member, "format": "CSV", "rows": len(out), "headers": reader.fieldnames[:80], "reason": "PARSED"}

def read_json_records(data: bytes, path_hint: str, market_hint: Optional[str], source_member: str) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    try:
        obj = json.loads(decode_bytes(data))
    except Exception as e:
        return [], {"member": source_member, "format": "JSON", "rows": 0, "reason": f"JSON_PARSE_ERROR:{type(e).__name__}"}
    out = []
    for _, row in json_dict_rows(obj):
        record = normalize_record(row, market_hint, path_hint, source_member, "JSON")
        if record:
            out.append(record)
    return out, {"member": source_member, "format": "JSON", "rows": len(out), "reason": "PARSED" if out else "NO_MATCHING_ROWS"}

