    candidates.append(path_hint)
    for raw in candidates:
        s = str(raw or "").strip()
        m = re.search(r"(?<!\d)(20\d{2})[-/]?(\d{2})[-/]?(\d{2})(?!\d)", s)
        if m:
            y, mo, d = map(int, m.groups())
