                pass
        m = re.search(r"(?<!\d)(\d{3})[/.-]?(\d{2})[/.-]?(\d{2})(?!\d)", s)
        if m:
            y, mo, d = map(int, m.groups())
            try:
                return dt.date(y + 1911, mo, d).isoformat()
            except ValueError:
                pass
    return None

