                data = gzip.decompress(zf.read(member))
                rows, meta = read_csv_records(data, name, market_hint, f"{label}!{name}")
                meta["format"] = "CSV.GZ"
            elif name.lower().endswith(".json.gz"):
                data = gzip.decompress(zf.read(member))
                rows, meta = read_json_records(data, name, market_hint, f"{label}!{name}")
                meta["format"] = "JSON.GZ"
